<?php
// Proposal 'stylemap' (owner 2026-10-11): "is the opponent aggro?" read from the meta's LEADER + BASE map (SWUSim/Custom/BotOpponentStyles.php,
// generated by SWUSim/DevTools/regen-opponent-styles.php from every real list we hold), instead of the hand-kept SWU_BOT_AGGRO_LEADERS.
// Expectations are DERIVED from the generated map, never pinned to its numbers — a regen after a classifier fix must not break this test.
//   docker exec -w /var/www/html/TCGEngine otmtcge-swusim-web-server-1 php -d apc.enable_cli=1 -d xdebug.mode=off SWUSim/DevTools/tests/bot_stylemap_test.php
require __DIR__ . '/fixtures/bot_test_bootstrap.php';
foreach (['BotLegalActions', 'Custom/BotLookahead', 'Custom/BotEvaluator', 'Rl/CardTags', 'Custom/BotStyles', 'Custom/BotResourcing',
          'Custom/BotGuides', 'Custom/BotFallback', 'Custom/BotRules', 'BotHeuristic'] as $f) include_once "./SWUSim/$f.php";
$check(in_array('stylemap', SWUBotProposalList(), true) && SWUBotVariantDisabled('try-stylemap') === ['try:stylemap'], 'stylemap is a switchable proposal');
$M = SWU_BOT_OPPONENT_STYLES;
$check(count($M) > 0, 'the generated map is loaded');

// ── The lookup's fallback order: exact base (n >= MIN), then the base's aspect (n >= MIN), then the leader alone (any n) ──────────────
$aspectOf = fn(string $b) => explode(',', strval(CardAspect($b) ?? ''))[0];
$exact = null; $thin = null;
foreach ($M as $k => $e) {
    if (str_ends_with($k, '|*') || str_contains($k, '|aspect:')) continue;
    [$l, $b] = explode('|', $k);
    if ($exact === null && $e['n'] >= SWU_BOT_STYLEMAP_MIN_N) $exact = [$l, $b, $e['rank']];
    $ak = "$l|aspect:" . $aspectOf($b);
    if ($thin === null && $e['n'] < SWU_BOT_STYLEMAP_MIN_N && ($M[$ak]['n'] ?? 0) >= SWU_BOT_STYLEMAP_MIN_N && $M[$ak]['rank'] != $e['rank'] && $M[$ak]['rank'] != ($M["$l|*"]['rank'] ?? null)) $thin = [$l, $b, $M[$ak]['rank']];
}
$check($exact !== null && SWUBotLeaderBaseStyleRank($exact[0], $exact[1]) == $exact[2], 'a well-sampled leader|base answers from its own key');
$check($thin !== null && SWUBotLeaderBaseStyleRank($thin[0], $thin[1]) == $thin[2], 'a thin leader|base (n < MIN) falls back to the base-aspect key');
$check(SWUBotLeaderBaseStyleRank('SOR_998', 'SOR_029') === null, 'a leader no real list has used returns null');

// ── Behaviour through SWUBotOpponentIsAggroLeader (every call site reads it) ────────────────────────────────────────────────────────
$vs = function (string $leader, string $base, bool $on) use ($build) {
    $build(function ($b) use ($leader, $base) { $b->MyLeader('LAW_008', false); $b->MyBase('LAW_021'); $b->TheirLeader($leader, false); $b->TheirBase($base); });
    SWUBotSetDisabledFeatures($on ? ['try:stylemap'] : []);
    $r = SWUBotOpponentIsAggroLeader(1); SWUBotSetDisabledFeatures([]);
    return $r;
};
$mapAggro = fn(string $l, string $b) => SWUBotLeaderBaseStyleRank($l, $b) < SWU_BOT_STYLEMAP_AGGRO_BELOW;
// Wicket (HMW_014): never on the hand list; the map reads his lists.
$check($vs('HMW_014', 'HMW_023', false) === false, 'premise: off, Wicket is not aggro (not on the hand list)');
$check($vs('HMW_014', 'HMW_023', true) === $mapAggro('HMW_014', 'HMW_023') && $mapAggro('HMW_014', 'HMW_023'), '@try-stylemap: Wicket reads aggro from the map');
// Boba Fett (JTL_009): the hand list says aggro for every base; the map splits Lake Country (JTL_031) from a blue base (ASH_019).
$check($vs('JTL_009', 'ASH_019', false) === true, 'premise: off, Boba on a blue base is aggro (hand list, leader only)');
$check($mapAggro('JTL_009', 'JTL_031') && !$mapAggro('JTL_009', 'ASH_019'), 'the map splits Boba by base (Lake Country aggro, blue base not)');
$check($vs('JTL_009', 'JTL_031', true) === true, '@try-stylemap: Boba on Lake Country is aggro');
$check($vs('JTL_009', 'ASH_019', true) === false, '@try-stylemap: Boba on a blue base is not');
// A SOFT aggro pairing (mean rank between 0.5 and the 1.5 cut) is aggro too — the cut is not "hyper only". Derived from the map.
$soft = null;
foreach ($M as $k => $e) {
    if (str_ends_with($k, '|*') || str_contains($k, '|aspect:') || $e['n'] < SWU_BOT_STYLEMAP_MIN_N || $e['rank'] < 0.5 || $e['rank'] >= SWU_BOT_STYLEMAP_AGGRO_BELOW) continue;
    $soft = explode('|', $k); break;
}
$check($soft !== null && $vs($soft[0], $soft[1], true) === true, '@try-stylemap: a soft-aggro leader|base (' . implode('|', $soft ?? []) . ') is aggro');
// A control leader stays not-aggro either way.
$check($vs('SEC_010', 'SEC_019', true) === false && $vs('SEC_010', 'SEC_019', false) === false, 'Dedra (hard control) is never aggro');
// A leader the map has never seen keeps the hand list's verdict: put a list leader's ID through a map with it removed.
$check(in_array('LAW_002', SWU_BOT_AGGRO_LEADERS, true), 'premise: Tobias Beckett is on the hand list');
$check($vs('LAW_002', 'SEC_019', true) === $mapAggro('LAW_002', 'SEC_019'), '@try-stylemap: Tobias Beckett follows the map, not the list');

bot_test_finish();
